from __future__ import annotations

import sys
from pathlib import Path

def _find_repo_root() -> Path:
    here = Path(__file__).resolve()
    for p in [here, *here.parents]:
        if (p / "src" / "cfnlint").is_dir():
            return p
    raise RuntimeError("Could not locate cfnlint source tree (expected .../src/cfnlint).")

_REPO_ROOT = _find_repo_root()
_SRC = _REPO_ROOT / "src"
if str(_SRC) not in sys.path:
    sys.path.insert(0, str(_SRC))

from cfnlint.template import Template
from cfnlint.template.transforms._language_extensions import _Transform

def _make_cfn(extra: dict) -> Template:
    template = {
        "Transform": ["AWS::LanguageExtensions"],
        "Mappings": {
            "Sizes": {
                "small": {"cpu": "256", "mem": "512"},
                "large": {"cpu": "1024", "mem": "2048"},
            }
        },
        "Parameters": {
            "Env": {
                "Type": "String",
                "AllowedValues": ["dev", "prod"],
                "Default": "dev",
            },
        },
        "Resources": {},
    }
    template.update(extra)
    return Template("", template)

class TestLanguageExtensionsWalkDefUsePairsQA:
    def test_language_extensions_walk_def_use_pairs_case(self):
        cfn_a = _make_cfn(
            {
                "Resources": {
                    "Fn::ForEach::EnvLoop": [
                        "Env",
                        ["dev", "prod"],
                        {
                            "Bucket${Env}": {
                                "Type": "AWS::S3::Bucket",
                                "Properties": {
                                    "BucketName": {"Fn::Sub": "${Env}-bucket"},
                                },
                            }
                        },
                    ]
                }
            }
        )
        errors, out = _Transform().transform(cfn_a)
        assert errors == []
        assert "Bucketdev" in out["Resources"]
        assert "Bucketprod" in out["Resources"]

        cfn_b = _make_cfn(
            {"Resources": {"X": {"Properties": {"P": {"Fn::ToJsonString": {"a": 1}}}}}}
        )
        _, out = _Transform().transform(cfn_b)
        assert "Fn::ToJsonString" in out["Resources"]["X"]["Properties"]["P"]

        cfn_c = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "ListForm": {"Fn::GetAtt": ["Resource1", "Arn"]},
                            "StrForm": {"Fn::GetAtt": "Resource1.Arn"},
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_c)
        assert out["Resources"]["X"]["Properties"]["ListForm"] is not None

        cfn_d = _make_cfn(
            {"Resources": {"X": {"Properties": {"P": {"Fn::Sub": "literal"}}}}}
        )
        _, out = _Transform().transform(cfn_d)

        cfn_e = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "P": {
                                "Fn::Sub": [
                                    "${Custom}-suffix",
                                    {"Custom": "rendered"},
                                ]
                            }
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_e)

        cfn_f = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "Cpu": {"Fn::FindInMap": ["Sizes", "small", "cpu"]},
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_f)
        assert out["Resources"]["X"]["Properties"]["Cpu"] == "256"

        cfn_g = _make_cfn(
            {
                "Resources": {
                    "X": {
                        "Properties": {
                            "Cpu": {
                                "Fn::FindInMap": [
                                    "MissingMap",
                                    {"Ref": "Env"},
                                    "cpu",
                                ]
                            }
                        }
                    }
                }
            }
        )
        _, out = _Transform().transform(cfn_g)

        cfn_h = _make_cfn(
            {
                "Resources": {
                    "Fn::ForEach::EnvLoop": [
                        "Env",
                        ["alpha"],
                        {
                            "Q${Env}": {
                                "Type": "AWS::Custom",
                                "Properties": {
                                    "InParams": {"Ref": "Env"},
                                    "NotInParams": {"Ref": "AWS::Region"},
                                    "DictRef": {"Ref": {"Fn::Sub": "Env"}},
                                },
                            }
                        },
                    ],
                }
            }
        )
        _, out = _Transform().transform(cfn_h)

        cfn_i = _make_cfn(
            {
                "Outputs": {
                    "Items": [
                        "literal-1",
                        {"Ref": "Env"},
                        42,
                        None,
                        {"Fn::Sub": "${Env}-x"},
                    ],
                },
            }
        )
        _, out = _Transform().transform(cfn_i)

        cfn_j = _make_cfn(
            {
                "Outputs": {
                    "Foo": {"Drop": None, "Keep": "kept"},
                },
            }
        )
        _, out = _Transform().transform(cfn_j)
        assert out["Outputs"]["Foo"].get("Keep") == "kept"

from __future__ import annotations

import argparse
import ast
import json
import re
from collections import defaultdict
from pathlib import Path

ROOT_DIR = Path("/testbed")
TARGET_FILE = ROOT_DIR / "src/cfnlint/template/transforms/_language_extensions.py"
TARGET_FUNC_QUAL = (
    "cfnlint.template.transforms._language_extensions._Transform._walk"
)
TARGET_CLASS_NAME = "_Transform"
TARGET_FUNC_NAME = "_walk"
INSTANCE_ID = "language_extensions_walk_def_use_pairs"
EXCLUDE_VARS: set[str] = {"self", "_"}

TRACE_RE = re.compile(
    r"^\d{4}-\d{2}-\d{2} .*? (?P<path>/testbed/[^:]+):(?P<lineno>\d+) "
    r"(?P<func>\S+) event=(?P<event>call|line|return|exception) ",
    re.MULTILINE,
)

def _is_target_path(path: str) -> bool:
    return path.replace("\\", "/").endswith(
        "cfnlint/template/transforms/_language_extensions.py"
    )

class DefUseVisitor(ast.NodeVisitor):

    def __init__(self) -> None:
        self.defs: dict[int, set[str]] = defaultdict(set)
        self.uses: dict[int, set[str]] = defaultdict(set)

    def visit_FunctionDef(self, node):
        return

    def visit_AsyncFunctionDef(self, node):
        return

    def visit_Lambda(self, node):
        return

    def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Store):
            self.defs[node.lineno].add(node.id)
        elif isinstance(node.ctx, ast.Load):
            self.uses[node.lineno].add(node.id)
        elif isinstance(node.ctx, ast.Del):
            self.defs[node.lineno].add(node.id)
        self.generic_visit(node)

def get_target_function_node(module: ast.Module) -> ast.FunctionDef:
    for node in module.body:
        if isinstance(node, ast.ClassDef) and node.name == TARGET_CLASS_NAME:
            for child in node.body:
                if (
                    isinstance(child, ast.FunctionDef)
                    and child.name == TARGET_FUNC_NAME
                ):
                    return child
    raise ValueError("Could not find target function node.")

def build_def_use_maps(
    file_text: str,
) -> tuple[dict[int, set[str]], dict[int, set[str]], set[str]]:
    module = ast.parse(file_text)
    func_node = get_target_function_node(module)

    visitor = DefUseVisitor()
    for stmt in func_node.body:
        visitor.visit(stmt)

    param_names = {arg.arg for arg in func_node.args.args}

    all_local_defs: set[str] = set()
    for names in visitor.defs.values():
        all_local_defs.update(names)

    tracked_vars = (all_local_defs | param_names) - EXCLUDE_VARS

    filtered_defs: dict[int, set[str]] = {}
    filtered_uses: dict[int, set[str]] = {}

    for line, names in visitor.defs.items():
        keep = {n for n in names if n in tracked_vars and n not in EXCLUDE_VARS}
        if keep:
            filtered_defs[line] = keep
    for line, names in visitor.uses.items():
        keep = {n for n in names if n in tracked_vars and n not in EXCLUDE_VARS}
        if keep:
            filtered_uses[line] = keep

    return filtered_defs, filtered_uses, tracked_vars

def extract_observed_pairs(
    trace_text: str,
    defs_by_line: dict[int, set[str]],
    uses_by_line: dict[int, set[str]],
    tracked_vars: set[str],
) -> list[dict[str, object]]:
    pairs: set[tuple[str, int, int]] = set()
    last_def_stack: list[dict[str, int]] = []

    for match in TRACE_RE.finditer(trace_text):
        path = match.group("path")
        func = match.group("func")
        event = match.group("event")
        lineno = int(match.group("lineno"))

        if not _is_target_path(path) or func != TARGET_FUNC_QUAL:
            continue

        if event == "call":
            last_def_stack.append({})
            continue
        if event == "return":
            if last_def_stack:
                last_def_stack.pop()
            continue
        if event == "exception":
            continue
        if event != "line" or not last_def_stack:
            continue

        current = last_def_stack[-1]
        for var in uses_by_line.get(lineno, set()):
            if var in current:
                pairs.add((var, current[var], lineno))
        for var in defs_by_line.get(lineno, set()):
            if var in tracked_vars:
                current[var] = lineno

    return [
        {"variable": var, "def_line": d, "use_line": u}
        for (var, d, u) in sorted(pairs, key=lambda x: (x[0], x[1], x[2]))
    ]

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--trace-log",
        default=f"/testbed/logs/qa_instances/{INSTANCE_ID}/trace.log",
    )
    parser.add_argument(
        "--out",
        default=f"/testbed/logs/qa_instances/{INSTANCE_ID}/oracle.json",
    )
    args = parser.parse_args()

    source_text = TARGET_FILE.read_text(encoding="utf-8")
    defs_by_line, uses_by_line, tracked_vars = build_def_use_maps(source_text)
    tracked_names_sorted = sorted(tracked_vars)

    trace_text = Path(args.trace_log).read_text(encoding="utf-8")
    observed_pairs = extract_observed_pairs(
        trace_text, defs_by_line, uses_by_line, tracked_vars
    )

    var_list = ", ".join(f"`{v}`" for v in tracked_names_sorted)

    qa = {
        "question_kind": "data_flow_prediction",
        "question": (
            "Use `tests/qa/testcase.py`, class "
            "`TestLanguageExtensionsWalkDefUsePairsQA`, method "
            "`test_language_extensions_walk_def_use_pairs_case`. Focus only on method "
            "`cfnlint.template.transforms._language_extensions._Transform._walk` in "
            "file `src/cfnlint/template/transforms/_language_extensions.py`. The "
            "method is recursive: it deepcopies its `item` parameter into local "
            "`obj`, then dispatches on type. Dict items go through a multi-arm "
            "branch (`Fn::ForEach`, `Fn::ToJsonString`, `Fn::GetAtt`, `Fn::Sub`, "
            "`Fn::FindInMap`, `Ref`, plus a generic recursive arm); list items go "
            "through `enumerate(obj)`; scalars fall through to `return obj`. "
            f"Track exactly these variable names: {var_list}. Do NOT track "
            "anything inside the nested helper `_replace_string_params` -- it is a "
            "separate function with its own scope. List all unique def-use pairs "
            "observed during this test run for this method (aggregating across "
            "every recursive call). Return the answer as `observed_def_use_pairs`, "
            "a list of objects with exactly these keys: `variable`, `def_line`, "
            "`use_line`. Each pair means the value assigned to `variable` at "
            "`def_line` is later read at `use_line` before being redefined within "
            "the SAME call frame. Sort the list by `variable`, then `def_line`, "
            "then `use_line`, all ascending."
        ),
        "template_answer": {
            "observed_def_use_pairs": [
                {"variable": "str", "def_line": "int", "use_line": "int"}
            ]
        },
        "oracle_answer": {
            "observed_def_use_pairs": observed_pairs,
        },
        "execution": {
            "trace_target": TARGET_FUNC_QUAL,
            "trace_events": ["line", "call", "return", "exception"],
            "pytest_nodeid": (
                "tests/qa/testcase.py::TestLanguageExtensionsWalkDefUsePairsQA::"
                "test_language_extensions_walk_def_use_pairs_case"
            ),
        },
    }

    out_path = Path(args.out)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(qa, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps(qa, indent=2, ensure_ascii=False))

if __name__ == "__main__":
    main()

